1	export type Item = {
2	  type: string;
3	};
4	
5	export type Scenario = {
6	  customer: { yearsWithMHPCO: number };
7	  steps: { op: string; items: Item[] }[];
8	};
9	
10	export type ScenarioResult = {
11	  results: { premium: number }[];
12	};
13	
14	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
23	const PROCESSING_FEE = 5;
24	
25	const percentOf = (amount: number, percent: number): number =>
26	  (amount * percent) / 100;
27	
28	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
29	
30	const BLOCK_SIZE = 3;
31	const BLOCK_BASE_PREMIUM = 60;
32	
33	const countByType = (items: Item[]): Map<string, number> =>
34	  items.reduce(
35	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
36	    new Map<string, number>(),
37	  );
38	
39	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
40	
41	const basePremiumForGroup = (type: string, count: number): number =>
42	  formsBuildingBlock(count)
43	    ? BLOCK_BASE_PREMIUM
44	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
45	
46	const policyBasePremium = (items: Item[]): number =>
47	  [...countByType(items)]
48	    .map(([type, count]) => basePremiumForGroup(type, count))
49	    .reduce((total, groupPremium) => total + groupPremium, 0);
50	
51	const quotePremium = (items: Item[]): number => {
52	  const basePremium = policyBasePremium(items);
53	  const withFirstInsuranceSurcharge =
54	    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
55	  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
56	};
57	
58	export const runScenario = (scenario: Scenario): ScenarioResult => ({
59	  results: scenario.steps.map((step) => ({
60	    premium: quotePremium(step.items),
61	  })),
62	});
